  box-shadow: 0 4px 12px rgba(0,0,0,.22);
}
.rail-btn svg { width: 19px; height: 19px; }

/* ---------------- hint ---------------- */
.hint-pill {
  position: absolute;
  left: 50%;
  bottom: calc(102px + var(--safe-b));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: min(540px, 70vw);
  padding: 8px 14px;
  border-radius: 20px;
  color: #deddd5;
  background: rgba(13, 14, 15, .78);
