.hot-slot:hover { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.28); }
.hot-slot.active {
  border-color: var(--green);
  background: linear-gradient(180deg, rgba(158,219,47,.24), rgba(158,219,47,.08));
