/* ---------------- drawer ---------------- */
.drawer {
  position: absolute;
  top: calc(76px + var(--safe-t));
  right: calc(16px + var(--safe-r));
  bottom: calc(88px + var(--safe-b));
  width: 392px;
  display: flex;
  flex-direction: column;
  padding: 15px 15px 12px;
  border-radius: 14px;
  background:
    linear-gradient(155deg, rgba(36,38,40,.97), rgba(14,15,16,.98) 55%),
    #151617;
  border: 1px solid rgba(255,255,255,.2);
  box-shadow: 0 18px 48px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.1);
  backdrop-filter: blur(12px);
  transform: translateX(calc(100% + 30px));
  opacity: 0;
  visibility: hidden;
  transition: transform .23s cubic-bezier(.2,.8,.25,1), opacity .18s, visibility .2s;
  overflow: hidden;
}
.drawer.open { transform: translateX(0); opacity: 1; visibility: visible; }
.drawer::before {
  content: '';
  position: absolute;
  top: 0; left: 18px; right: 18px;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--green), transparent);
  opacity: .7;
}
.drawer-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
.drawer-eyebrow { font-size: 7px; font-weight: 800; letter-spacing: 2px; color: var(--green); margin-bottom: 4px; }
.drawer-head h1 {
  font-family: 'Bungee', sans-serif;
