  border: 1px solid rgba(255,255,255,.14);
  display: grid; place-items: center;
}
.close-btn svg { width: 15px; height: 15px; stroke: #e8e7df; stroke-width: 2.4; stroke-linecap: round; fill: none; }
.close-btn:hover { background: var(--danger); }

.drawer-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
  margin: 12px 0 10px;
}
.tab-btn {
  position: relative;
  padding: 6px 2px 5px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  border-radius: 7px;
  border: 1px solid transparent;
  color: #898b86;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .8px;
  transition: .13s;
}
.tab-btn svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.tab-btn:hover { color: #e8e7df; background: rgba(255,255,255,.05); }
.tab-btn.active { color: var(--green); background: rgba(158,219,47,.1); border-color: rgba(158,219,47,.3); }
.tab-btn.active::after {
  content: '';
  position: absolute; bottom: -5px; left: 20%; right: 20%;
  height: 2px; background: var(--green); border-radius: 2px;
}

.drawer-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,.2) transparent;
  padding-right: 2px;
  touch-action: pan-y;
}
.item-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}
.item-card {
  position: relative;
  min-height: 84px;
  padding: 6px 3px 5px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(255,255,255,.075), rgba(255,255,255,.025));
  border: 1px solid rgba(255,255,255,.1);
  transition: .12s;
  overflow: hidden;
