}
.stock { display: flex; align-items: center; gap: 5px; font-size: 6.5px; font-weight: 800; letter-spacing: .9px; color: #8b8d88; }
.stock-light { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 6px var(--green); }
.clear-btn {
