  background: rgba(240,84,79,.08);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: .8px;
}
.clear-btn:hover { background: rgba(240,84,79,.2); }

/* ---------------- toast ---------------- */
.toast {
  position: absolute;
  left: 50%;
  top: calc(86px + var(--safe-t));
  transform: translate(-50%, -8px);
  padding: 8px 15px;
  border-radius: 7px;
  background: rgba(13,14,15,.94);
  border: 1px solid rgba(158,219,47,.45);
  color: #eaf7cf;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .4px;
  opacity: 0;
  visibility: hidden;
  transition: .2s;
  pointer-events: none;
  box-shadow: 0 5px 20px rgba(0,0,0,.35);
}
.toast.show { opacity: 1; visibility: visible; transform: translate(-50%, 0); }

/* ---------------- pause modal ---------------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  background: rgba(8, 9, 10, .64);
  backdrop-filter: blur(5px);
  opacity: 0;
  visibility: hidden;
  transition: .2s;
}
.modal-backdrop.open { opacity: 1; visibility: visible; }
