  color: #172006;
  border: 1px solid #182107;
  box-shadow: 0 3px 0 #537a0b, 0 5px 12px rgba(0,0,0,.2);
}
.primary-btn:hover { filter: brightness(1.06); }
.primary-btn:active { transform: translateY(2px); box-shadow: 0 1px 0 #537a0b; }
.ghost-btn {
  color: #d9d8d0;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.14);
}
.ghost-btn:hover { background: rgba(255,255,255,.12); }
.modal-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 17px;
  padding-top: 11px;
  border-top: 1px solid rgba(255,255,255,.1);
  font-size: 6.5px;
  letter-spacing: 1px;
  font-weight: 800;
  color: #7d7f7a;
}
.modal-meta b { color: var(--green); }

/* ---------------- rotate ---------------- */
.rotate-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 30px;
  background:
    radial-gradient(circle at 50% 35%, rgba(158,219,47,.1), transparent 45%),
    #121315;
  text-align: center;
}
.rotate-overlay.show { display: flex; }
.rotate-phone { position: relative; width: 138px; height: 138px; margin-bottom: 8px; }
.phone-body {
  position: absolute;
  left: 50%; top: 50%;
  width: 46px; height: 84px;
  margin: -42px 0 0 -23px;
  border: 3px solid #e8e7df;
  border-radius: 9px;
  transform: rotate(0deg);
  animation: phone-tilt 2.4s ease-in-out infinite;
}
.phone-body span {
  position: absolute; left: 50%; bottom: 5px;
  width: 12px; height: 2px; margin-left: -6px;
  background: #e8e7df; border-radius: 2px;
}
.rotate-arrow {
  position: absolute; inset: 8px;
  width: 122px; height: 122px;
  fill: none; stroke: var(--green); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round;
  opacity: .85;
}
@keyframes phone-tilt {
  0%, 22% { transform: rotate(0deg); }
  55%, 78% { transform: rotate(-90deg); }
  100% { transform: rotate(0deg); }
}
.rotate-overlay h2 { font-family: 'Bungee', sans-serif; margin: 0; font-size: 26px; letter-spacing: .5px; }
.rotate-overlay p { margin: 2px 0 15px; color: #a4a6a1; font-size: 12px; max-width: 280px; }
