+
+    const affected = new Set();
+    const bodies = Composite.allBodies(world);
+    for (const body of bodies) {
+      if (!body || body.isStatic) continue;
+      const dx = body.position.x - x;
+      const dy = body.position.y - y;
+      const d = Math.hypot(dx, dy);
