    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.stroke();
    ctx.fillStyle = '#c9a22d';
    ctx.fillRect(-2, -16, 4, 6);
    if (Math.sin(sceneTime * 18) > 0.2) {
