    ctx.beginPath(); ctx.moveTo(8, -14); ctx.quadraticCurveTo(16, -28, 5, -32); ctx.stroke();
    ctx.fillStyle = Math.sin(sceneTime * 22) > 0 ? '#ffd24a' : '#ff5b22';
