738:     torso: { w: 44, h: 150 },
739:     head: { w: 56, h: 52 },
740:     armL1: { w: 15, h: 62 },
741:     armL2: { w: 14, h: 56 },
742:     armR1: { w: 15, h: 62 },
743:     armR2: { w: 14, h: 56 },
744:     legL1: { w: 18, h: 66 },
