750:   function createRagdoll(x, feetY, palKey, opts = {}) {
751:     const pal = PALETTES[palKey] || PALETTES.green;
752:     const r = {
753:       id: ++ragdollSerial,
754:       palKey,
755:       pal,
756:       parts: {},
757:       constraints: [],
758:       health: 100,
759:       dead: false,
760:       standing: opts.standing !== false,
761:       homeX: x,
762:       feetY,
763:       weapon: opts.weapon || null,
764:       weaponFlash: 0,
765:       weaponTimer: 0,
766:       hitFlash: 0,
767:       showHealth: 0,
768:       blinkAt: rand(1, 5),
769:       blink: 0,
770:       seed: rand(0, 100),
771:       frozenUntil: 0,
772:       spikeCooldown: 0,
773:       severed: new Set()
774:     };
775: 
776:     const torsoY = feetY - 201;
777:     const shoulderY = torsoY - 52;
778:     const hipY = torsoY + 75;
779:     const bodyOpts = {
780:       friction: 0.75,
781:       frictionAir: 0.012,
782:       restitution: 0.04,
783:       density: 0.0022,
784:       slop: 0.02,
785:       collisionFilter: { category: 0x0002, mask: 0xffffffff }
786:     };
787: 
788:     const torso = Bodies.rectangle(x, torsoY, 44, 150, bodyOpts);
789:     const head = Bodies.rectangle(x, torsoY - 101, 56, 52, { ...bodyOpts, density: 0.003 });
790:     const armL1 = Bodies.rectangle(x - 31, shoulderY + 31, 15, 62, bodyOpts);
791:     const armL2 = Bodies.rectangle(x - 31, shoulderY + 90, 14, 56, bodyOpts);
792:     const armR1 = Bodies.rectangle(x + 31, shoulderY + 31, 15, 62, bodyOpts);
793:     const armR2 = Bodies.rectangle(x + 31, shoulderY + 90, 14, 56, bodyOpts);
794:     const legL1 = Bodies.rectangle(x - 11, hipY + 33, 18, 66, bodyOpts);
795:     const legL2 = Bodies.rectangle(x - 11, hipY + 96, 17, 60, bodyOpts);
796:     const legR1 = Bodies.rectangle(x + 11, hipY + 33, 18, 66, bodyOpts);
797:     const legR2 = Bodies.rectangle(x + 11, hipY + 96, 17, 60, bodyOpts);
798: 
799:     r.parts = { torso, head, armL1, armL2, armR1, armR2, legL1, legL2, legR1, legR2 };
800:     Object.entries(r.parts).forEach(([name, body]) => {
801:       const d = PART_DIMS[name];
802:       body.plugin = { type: 'part', ragdoll: r, partName: name, w: d.w, h: d.h };
803:     });
804: 
805:     const addJoint = (a, b, pa, pb, stiffness = 0.92) => {
806:       const c = Constraint.create({
807:         bodyA: a, pointA: pa,
808:         bodyB: b, pointB: pb,
809:         length: 0, stiffness, damping: 0.12,
810:         render: { visible: false }
811:       });
812:       c.plugin = { ragdoll: r, partA: a.plugin.partName, partB: b.plugin.partName };
813:       Composite.add(world, c);
814:       r.constraints.push(c);
815:       return c;
816:     };
817: 
818:     addJoint(torso, head, { x: 0, y: -75 }, { x: 0, y: 26 }, 0.95);
819:     addJoint(torso, armL1, { x: -24, y: -52 }, { x: 0, y: -31 });
820:     addJoint(armL1, armL2, { x: 0, y: 31 }, { x: 0, y: -28 });
821:     addJoint(torso, armR1, { x: 24, y: -52 }, { x: 0, y: -31 });
822:     addJoint(armR1, armR2, { x: 0, y: 31 }, { x: 0, y: -28 });
823:     addJoint(torso, legL1, { x: -11, y: 75 }, { x: 0, y: -33 }, 0.95);
824:     addJoint(legL1, legL2, { x: 0, y: 33 }, { x: 0, y: -30 }, 0.95);
825:     addJoint(torso, legR1, { x: 11, y: 75 }, { x: 0, y: -33 }, 0.95);
826:     addJoint(legR1, legR2, { x: 0, y: 33 }, { x: 0, y: -30 }, 0.95);
827: 
828:     Composite.add(world, Object.values(r.parts));
829:     ragdolls.push(r);
830: 
831:     while (ragdolls.length > 9) removeRagdoll(ragdolls[0]);
832:     updateVictimCount();
833:     return r;
834:   }
