836:   function stabilizeRagdoll(r) {
837:     if (!r.standing || r.dead || sceneTime < r.frozenUntil) return;
838:     const torso = r.parts.torso;
839:     const target = 0;
840:     Body.setAngularVelocity(torso, torso.angularVelocity * 0.8 + normAngle(target - torso.angle) * 0.09);
841:     const targets = [
842:       ['head', 0.02], ['armL1', 0.02], ['armL2', 0.04],
843:       ['armR1', -0.02], ['armR2', -0.04], ['legL1', 0.01],
844:       ['legL2', 0.01], ['legR1', -0.01], ['legR2', -0.01]
845:     ];
846:     for (const [name, bias] of targets) {
847:       if (r.severed.has(name)) continue;
848:       const b = r.parts[name];
849:       if (!b) continue;
850:       const diff = normAngle(torso.angle + bias - b.angle);
851:       Body.setAngularVelocity(b, b.angularVelocity * 0.76 + diff * 0.085);
852:     }
853:     // gentle centre spring, enough to keep a standing pose but not enough to fight a real hit
854:     const dx = r.homeX - torso.position.x;
855:     if (Math.abs(dx) > 2) {
856:       Body.setVelocity(torso, { x: torso.velocity.x * 0.93 + dx * 0.0009, y: torso.velocity.y });
857:     }
858:   }
859: 
860:   function isPartAttached(r, name) {
861:     return r.constraints.some(c => c.plugin && (c.plugin.partA === name || c.plugin.partB === name));
862:   }
863: 
864:   function detachPart(r, name, impulse = 0) {
865:     if (!r.parts[name] || r.severed.has(name)) return;
866:     const parentJoint = {
867:       head: c => c.plugin.partB === 'head',
868:       armL1: c => c.plugin.partA === 'armL1' && c.plugin.partB === 'torso',
869:       armL2: c => c.plugin.partA === 'armL1' && c.plugin.partB === 'armL2',
870:       armR1: c => c.plugin.partA === 'armR1' && c.plugin.partB === 'torso',
871:       armR2: c => c.plugin.partA === 'armR1' && c.plugin.partB === 'armR2',
872:       legL1: c => c.plugin.partA === 'legL1' && c.plugin.partB === 'torso',
873:       legL2: c => c.plugin.partA === 'legL1' && c.plugin.partB === 'legL2',
874:       legR1: c => c.plugin.partA === 'legR1' && c.plugin.partB === 'torso',
875:       legR2: c => c.plugin.partA === 'legR1' && c.plugin.partB === 'legR2'
876:     }[name];
877:     if (!parentJoint) return;
878:     const idx = r.constraints.findIndex(parentJoint);
879:     if (idx < 0) return;
880:     Composite.remove(world, r.constraints[idx]);
881:     r.constraints.splice(idx, 1);
882:     r.severed.add(name);
883:     r.standing = false;
884:     const b = r.parts[name];
885:     addBlood(b.position.x, b.position.y, 16, 1.3);
886:     if (impulse) {
887:       Body.setVelocity(b, {
888:         x: b.velocity.x + rand(-1, 1) * impulse,
889:         y: b.velocity.y - rand(1, 2) * impulse
890:       });
891:       Body.setAngularVelocity(b, b.angularVelocity + rand(-0.35, 0.35));
892:     }
893:     if (name === 'head') {
894:       r.dead = true;
895:       r.health = 0;
896:       addBlood(b.position.x, b.position.y, 30, 1.6);
897:     }
898:   }
