900:   function damageRagdoll(r, amount, point, opts = {}) {
901:     if (!r) return;
902:     r.standing = false;
903:     r.hitFlash = 0.22;
904:     r.showHealth = 2.2;
905:     r.health -= amount;
906:     if (point) addBlood(point.x, point.y, opts.blood ?? 9, opts.power ?? 1);
907:     if (r.health <= 0 && !r.dead) {
908:       r.dead = true;
909:       r.health = 0;
910:       r.weapon = null;
911:       addBlood(r.parts.torso.position.x, r.parts.torso.position.y - 30, 26, 1.4);
912:     }
913:     if (opts.detach && Math.random() < opts.detachChance) {
914:       const choices = ['armL2', 'armR2', 'legL2', 'legR2', 'armL1', 'legL1'];
915:       detachPart(r, pick(choices), opts.impulse ?? 3);
916:     }
917:   }
