920:   function spawnProp(kind, x, y, opts = {}) {
921:     const isStatic = kind === 'spikes' || kind === 'trampoline';
922:     let w = 80, h = 80, density = 0.003, friction = 0.65, restitution = 0.08;
923:     if (kind === 'barrel') { w = 58; h = 80; density = 0.0025; }
924:     if (kind === 'wall') { w = 38; h = 168; density = 0.007; }
925:     if (kind === 'platform') { w = 220; h = 26; density = 0.005; }
926:     if (kind === 'spikes') { w = 150; h = 26; }
927:     if (kind === 'trampoline') { w = 150; h = 22; restitution = 1.35; friction = 0.9; }
928:     const cy = clamp(y, 60 + h / 2, WORLD.groundY - h / 2);
929:     const body = Bodies.rectangle(clamp(x, 80, WORLD.w - 80), cy, w, h, {
930:       isStatic,
931:       density,
932:       friction,
933:       frictionAir: 0.012,
934:       restitution,
935:       slop: 0.02,
936:       collisionFilter: { category: 0x0004, mask: 0xffffffff }
937:     });
938:     body.plugin = {
939:       type: 'prop',
940:       kind,
941:       w, h,
942:       hp: kind === 'barrel' ? 45 : kind === 'crate' ? 85 : kind === 'wall' ? 220 : 999,
943:       explosive: kind === 'barrel',
944:       exploded: false,
945:       seed: rand(0, 100)
946:     };
947:     Composite.add(world, body);
948:     props.push(body);
949:     if (!opts.silent) {
950:       addSmoke(body.position.x, body.position.y, 4, 0.55, 'rgba(130,128,116,');
951:       playSfx('spawn');
952:     }
953:     return body;
954:   }
