956:   function damageProp(body, amount, point) {
957:     if (!body || !body.plugin || body.plugin.type !== 'prop') return;
958:     const p = body.plugin;
959:     if (p.kind === 'spikes' || p.kind === 'trampoline') return;
960:     p.hp -= amount;
961:     if (point) addDebris(point.x, point.y, 3, p.kind === 'barrel' ? '#b9362e' : '#9b6a38');
962:     if (p.explosive && p.hp <= 0 && !p.exploded) {
963:       p.exploded = true;
964:       const pos = { ...body.position };
965:       removeProp(body);
966:       explode(pos.x, pos.y, 175, 23, 85);
967:     } else if (p.hp <= 0) {
968:       const pos = { ...body.position };
969:       if (p.kind === 'crate') addDebris(pos.x, pos.y, 14, '#9b6a38');
970:       if (p.kind === 'wall') addDebris(pos.x, pos.y, 20, '#8b8b85');
971:       addSmoke(pos.x, pos.y, 8, 1, 'rgba(120,116,104,');
972:       removeProp(body);
973:     }
974:   }
