1070:   // ---------------------------------------------------------------- explosions
1071:   function explode(x, y, radius = 150, power = 20, damage = 70) {
1072:     shake = Math.max(shake, clamp(radius / 9, 7, 24));
1073:     flash = Math.max(flash, clamp(radius / 340, 0.14, 0.48));
1074:     flashColor = '255,180,80';
1075:     playSfx(radius > 300 ? 'boom' : 'explosion');
1076:     addEffect({ type: 'ring', x, y, r0: 10, r1: radius * 1.35, life: 0.55, color: '255,220,150', width: 7 });
1077:     addEffect({ type: 'ring', x, y, r0: 4, r1: radius * 0.75, life: 0.3, color: '255,255,230', width: 14 });
1078:     addSmoke(x, y, Math.round(radius / 16), clamp(radius / 150, 0.7, 1.8));
1079:     addFire(x, y, Math.round(radius / 9), clamp(radius / 130, 0.7, 1.7));
1080:     addSparks(x, y, Math.round(radius / 9), '#ffd36a');
1081:     addDebris(x, y, Math.round(radius / 18), '#56524a');
1082:     addDecal(x, Math.max(WORLD.groundY - 3, y), 'scorch', clamp(radius / 110, 0.6, 2));
1083: 
1084:     const affected = new Set();
1085:     const bodies = Composite.allBodies(world);
1086:     for (const body of bodies) {
1087:       if (!body || body.isStatic) continue;
1088:       const dx = body.position.x - x;
1089:       const dy = body.position.y - y;
1090:       const d = Math.hypot(dx, dy);
1091:       if (d > radius || d < 0.001) continue;
1092:       const f = 1 - d / radius;
1093:       const nx = dx / d;
1094:       const ny = dy / d;
1095:       const mass = body.mass || 1;
1096:       Body.setVelocity(body, {
1097:         x: body.velocity.x + nx * power * f * (0.5 + Math.min(1.4, mass)),
1098:         y: body.velocity.y + ny * power * f * (0.5 + Math.min(1.4, mass)) - 4 * f
1099:       });
1100:       Body.setAngularVelocity(body, body.angularVelocity + rand(-0.18, 0.18) * f);
1101:       if (body.plugin?.type === 'part') affected.add(body.plugin.ragdoll);
1102:       if (body.plugin?.type === 'prop') {
1103:         if (body.plugin.explosive && !body.plugin.exploded) {
1104:           body.plugin.hp -= 70;
1105:           if (body.plugin.hp <= 0) {
1106:             body.plugin.exploded = true;
1107:             const pos = { ...body.position };
1108:             removeProp(body);
1109:             setTimeout(() => explode(pos.x, pos.y, 150, 18, 65), 90);
1110:           }
1111:         } else {
1112:           damageProp(body, damage * 2.2 * f, body.position);
1113:         }
1114:       }
1115:     }
1116:     for (const r of [...affected]) {
1117:       const d = Math.hypot(r.parts.torso.position.x - x, r.parts.torso.position.y - y);
1118:       const f = 1 - clamp(d / radius, 0, 1);
1119:       damageRagdoll(r, damage * f, { x: r.parts.torso.position.x, y: r.parts.torso.position.y }, {
1120:         blood: Math.round(12 + f * 20),
1121:         power: 1 + f,
1122:         detach: f > 0.28,
1123:         detachChance: f * 0.95,
