3385:   function frame(now) {
3386:     const raw = Math.min(0.05, (now - lastFrame) / 1000);
3387:     lastFrame = now;
3388:     if (!state.paused) {
3389:       accumulator += raw;
3390:       let steps = 0;
3391:       while (accumulator >= STEP && steps < 3) {
3392:         Engine.update(engine, STEP * 1000);
3393:         update(STEP);
3394:         accumulator -= STEP;
3395:         steps++;
3396:       }
3397:       if (steps === 3) accumulator = 0;
3398:     }
3399:     render(now);
3400:     requestAnimationFrame(frame);
3401:   }
