async (page) => {
  const errors = [];
  const logs = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => {
    const t = m.text();
    if (m.type() === 'error') errors.push('CONSOLE: ' + t);
    else logs.push(m.type() + ': ' + t);
  });

  await page.reload();
  await page.waitForFunction(() => window.__melonReady === true, null, { timeout: 15000 });
  await page.waitForTimeout(800);

  const size = await page.evaluate(() => ({ w: innerWidth, h: innerHeight }));
  const snap = async () => page.evaluate(() => ({
    ragdolls: window.__melon.ragdolls.length,
    props: window.__melon.props.length,
    projectiles: window.__melon.projectiles.length,
    particles: window.__melon.particles.length,
    effects: window.__melon.effects.length,
    tool: window.__melon.state.tool,
    paused: window.__melon.state.paused,
    drawer: window.__melon.state.drawerOpen,
    toolName: document.getElementById('toolName').textContent,
    hint: document.getElementById('hintText').textContent,
    toast: document.getElementById('toast').textContent
  }));

  const results = { size, categories: {}, items: [], actions: {}, errors };

  // Drawer + categories
  await page.click('#btnShop');
  await page.waitForTimeout(250);
  results.categories.open = await snap();
  for (const cat of ['living', 'weapons', 'build', 'fun']) {
    await page.click(`.tab-btn[data-cat="${cat}"]`);
    await page.waitForTimeout(80);
    results.categories[cat] = await page.evaluate(() =>
      [...document.querySelectorAll('.item-card')].map(c => ({
        id: c.dataset.id,
        name: c.querySelector('span').textContent,
        w: c.querySelector('canvas').width,
        h: c.querySelector('canvas').height
      }))
    );
  }

  // Helpers
  const selectItem = async (cat, id) => {
    if (!(await page.evaluate(() => window.__melon.state.drawerOpen))) {
      await page.click('#btnShop');
      await page.waitForTimeout(150);
    }
    await page.click(`.tab-btn[data-cat="${cat}"]`);
    await page.waitForTimeout(60);
    await page.click(`.item-card[data-id="${id}"]`);
    await page.waitForTimeout(160);
  };
  const clickCanvas = async (x, y, holdMs = 0) => {
    await page.mouse.move(x, y);
    await page.mouse.down();
    if (holdMs) await page.waitForTimeout(holdMs);
    await page.mouse.up();
    await page.waitForTimeout(220);
  };
  const reset = async () => {
    await page.click('#btnReset');
    await page.waitForTimeout(450);
  };

  // Test every living item spawns
  const livingIds = results.categories.living.map(i => i.id);
  for (const id of livingIds) {
    await reset();
    await selectItem('living', id);
    const before = await snap();
    await clickCanvas(640, 400);
    const after = await snap();
    results.items.push({ cat: 'living', id, toolName: after.toolName, before: before.ragdolls, after: after.ragdolls, toast: after.toast });
  }

  // Build items
  const buildIds = results.categories.build.map(i => i.id);
  for (const id of buildIds) {
    await reset();
    await selectItem('build', id);
    const before = await snap();
    await clickCanvas(620, 430);
    const after = await snap();
    results.items.push({ cat: 'build', id, toolName: after.toolName, before: before.props, after: after.props, toast: after.toast });
  }

  // Weapons
  const weaponIds = results.categories.weapons.map(i => i.id);
  for (const id of weaponIds) {
    await reset();
    await selectItem('weapons', id);
    const before = await snap();
    const auto = id === 'minigun' || id === 'flame';
