  for (const id of funIds) {
    await reset();
    await selectItem('fun', id);
    const before = await snap();
    await clickCanvas(600, 430);
    await page.waitForTimeout(500);
    const after = await snap();
    results.items.push({
      cat: 'fun', id, toolName: after.toolName, before: before.ragdolls,
      after: after.ragdolls, projectiles: after.projectiles, particles: after.particles,
      effects: after.effects, toast: after.toast
    });
  }

  // Undo / clear / reset
  await reset();
  await selectItem('living', 'melon');
  await clickCanvas(600, 420);
  const undoBefore = await snap();
  await page.click('#btnUndo');
  await page.waitForTimeout(200);
