    modal: document.getElementById('pauseModal').classList.contains('open'),
    victims: document.getElementById('victimCount').textContent
  }));
  await page.click('#btnResume');
  await page.waitForTimeout(150);
  results.actions.pauseResume = await page.evaluate(() => ({
    paused: window.__melon.state.paused,
    modal: document.getElementById('pauseModal').classList.contains('open')
  }));

  // Mute
  const muteBefore = await page.evaluate(() => window.__melon.state.muted);
  await page.click('#btnMute');
  await page.waitForTimeout(120);
  const muteAfter = await page.evaluate(() => ({ muted: window.__melon.state.muted, off: document.getElementById('btnMute').classList.contains('is-off') }));
  await page.click('#btnMute');
  results.actions.mute = { before: muteBefore, after: muteAfter };

  // Drag with hand: pick torso of first ragdoll, drag right
  await reset();
  await selectItem('living', 'melon'); // then switch to hand via hotbar
  await page.click('.hot-slot[data-id="hand"]');
  await page.waitForTimeout(120);
  const dragBefore = await page.evaluate(() => {
    const r = window.__melon.ragdolls[0];
    return { x: r.parts.torso.position.x, y: r.parts.torso.position.y };
  });
  // screen coord of first ragdoll torso
  const ds = await page.evaluate(() => {
    const r = window.__melon.ragdolls[0];
    return { x: r.parts.torso.position.x, y: r.parts.torso.position.y };
  });
  // camera is 800,450, scale .64 for 1024x576
  const sx = 512 + (ds.x - 800) * 0.64;
  const sy = 288 + (ds.y - 450) * 0.64;
  await page.mouse.move(sx, sy);
  await page.mouse.down();
  await page.mouse.move(sx + 80, sy - 40, { steps: 8 });
  await page.waitForTimeout(350);
  await page.mouse.up();
  await page.waitForTimeout(300);
  const dragAfter = await page.evaluate(() => {
    const r = window.__melon.ragdolls[0];
    return { x: r.parts.torso.position.x, y: r.parts.torso.position.y };
  });
  results.actions.drag = { before: dragBefore, after: dragAfter };

  // Hotbar switching
  const hot = await page.evaluate(() => [...document.querySelectorAll('.hot-slot')].map(s => s.dataset.id));
  results.actions.hotbar = hot;
  for (let i = 0; i < hot.length; i++) {
    await page.keyboard.press(String(i + 1));
    await page.waitForTimeout(80);
    const t = await page.evaluate(() => window.__melon.state.tool);
    results.actions['key' + (i + 1)] = { expected: hot[i], actual: t };
  }

  results.final = await snap();
  return results;
}

