await (async (page) => {
  page.setDefaultTimeout(8000);
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push('CONSOLE: ' + m.text()); });
  const progress = [];
  const mark = async (s) => { progress.push(s); await page.evaluate(m => { window.__audit = (window.__audit || []).concat(m); }, s); };
  const domClick = async (sel) => { await page.evaluate(s => { const el = document.querySelector(s); if (!el) throw new Error('missing ' + s); el.click(); }, sel); await page.waitForTimeout(90); };
  const snap = async () => page.evaluate(() => ({
    ragdolls: window.__melon.ragdolls.length,
    props: window.__melon.props.length,
    projectiles: window.__melon.projectiles.length,
    particles: window.__melon.particles.length,
    effects: window.__melon.effects.length,
    tool: window.__melon.state.tool,
    drawer: window.__melon.state.drawerOpen,
    paused: window.__melon.state.paused,
    toolName: document.getElementById('toolName').textContent,
    toast: document.getElementById('toast').textContent
  }));
  const results = { errors, progress, categories: {}, items: [], actions: {} };

  await page.waitForFunction(() => window.__melonReady === true);
  await page.waitForTimeout(500);
  results.size = await page.evaluate(() => ({ w: innerWidth, h: innerHeight, dpr: devicePixelRatio }));

  // Drawer/categories
  await domClick('#btnShop');
  results.categories.open = await snap();
  for (const cat of ['living', 'weapons', 'build', 'fun']) {
    await domClick(`.tab-btn[data-cat="${cat}"]`);
    results.categories[cat] = await page.evaluate(() =>
      [...document.querySelectorAll('.item-card')].map(c => ({ id: c.dataset.id, name: c.querySelector('span').textContent }))
    );
  }

  const selectItem = async (cat, id) => {
    const open = await page.evaluate(() => window.__melon.state.drawerOpen);
    if (!open) await domClick('#btnShop');
    await domClick(`.tab-btn[data-cat="${cat}"]`);
    await domClick(`.item-card[data-id="${id}"]`);
    await page.waitForTimeout(300); // let drawer slide out
  };
  const canvasClick = async (x, y, holdMs = 0) => {
    await page.mouse.move(x, y);
    await page.mouse.down();
    if (holdMs) await page.waitForTimeout(holdMs);
    await page.mouse.up();
    await page.waitForTimeout(250);
  };
  const reset = async () => { await domClick('#btnReset'); await page.waitForTimeout(500); };

  const runItem = async (cat, id) => {
    try {
      await mark(cat + ':' + id + ':start');
      await reset();
      await selectItem(cat, id);
      const before = await snap();
      const auto = id === 'minigun' || id === 'flame';
      let tx = 620, ty = 420;
      if (cat === 'weapons') { tx = 345; ty = 332; }
      await canvasClick(tx, ty, auto ? 600 : 0);
      await page.waitForTimeout(auto ? 500 : 400);
      const after = await snap();
      results.items.push({ cat, id, toolName: after.toolName, before, after, toast: after.toast });
      await mark(cat + ':' + id + ':done');
    } catch (e) {
      results.items.push({ cat, id, error: String(e).slice(0, 300) });
      await mark(cat + ':' + id + ':ERR ' + String(e).slice(0, 120));
    }
  };

  for (const it of results.categories.living) await runItem('living', it.id);
  for (const it of results.categories.build) await runItem('build', it.id);
  for (const it of results.categories.weapons) await runItem('weapons', it.id);
  for (const it of results.categories.fun) await runItem('fun', it.id);

  // Undo
  try {
    await reset();
    await selectItem('living', 'melon');
    await canvasClick(600, 420);
    const b = await snap();
    await domClick('#btnUndo');
    await page.waitForTimeout(200);
    const a = await snap();
    results.actions.undo = { before: b.ragdolls, after: a.ragdolls, toast: a.toast };
  } catch (e) { results.actions.undo = String(e); }

  // Clear
  try {
    if (!(await page.evaluate(() => window.__melon.state.drawerOpen))) await domClick('#btnShop');
    await domClick('#btnClear');
    await page.waitForTimeout(250);
    const a = await snap();
    results.actions.clear = { ragdolls: a.ragdolls, props: a.props, toast: a.toast };
  } catch (e) { results.actions.clear = String(e); }

  // Reset
  try {
    await reset();
    results.actions.reset = await snap();
  } catch (e) { results.actions.reset = String(e); }

  // Pause
  try {
    await domClick('#btnPause');
    await page.waitForTimeout(120);
    results.actions.pauseOpen = await page.evaluate(() => ({
      paused: window.__melon.state.paused,
      modal: document.getElementById('pauseModal').classList.contains('open'),
      victims: document.getElementById('victimCount').textContent
    }));
    await domClick('#btnResume');
    await page.waitForTimeout(120);
    results.actions.pauseResume = await page.evaluate(() => ({
      paused: window.__melon.state.paused,
      modal: document.getElementById('pauseModal').classList.contains('open')
    }));
  } catch (e) { results.actions.pause = String(e); }

  // Mute
  try {
    const before = await page.evaluate(() => window.__melon.state.muted);
    await domClick('#btnMute');
    const after = await page.evaluate(() => ({ muted: window.__melon.state.muted, off: document.getElementById('btnMute').classList.contains('is-off') }));
    await domClick('#btnMute');
    results.actions.mute = { before, after };
  } catch (e) { results.actions.mute = String(e); }

  // Drag
  try {
    await reset();
    await domClick('.hot-slot[data-id="hand"]');
    await page.waitForTimeout(250);
    const p0 = await page.evaluate(() => {
      const r = window.__melon.ragdolls[0];
      return { x: r.parts.torso.position.x, y: r.parts.torso.position.y };
    });
    const sx = 512 + (p0.x - 800) * 0.64;
    const sy = 288 + (p0.y - 450) * 0.64;
    await page.mouse.move(sx, sy);
    await page.mouse.down();
    await page.mouse.move(sx + 70, sy - 45, { steps: 6 });
    await page.waitForTimeout(350);
    await page.mouse.up();
    await page.waitForTimeout(300);
    const p1 = await page.evaluate(() => {
      const r = window.__melon.ragdolls[0];
      return { x: r.parts.torso.position.x, y: r.parts.torso.position.y };
    });
    results.actions.drag = { before: p0, after: p1 };
  } catch (e) { results.actions.drag = String(e); }

  // Hotbar + keyboard
  try {
    results.actions.hotbar = await page.evaluate(() => [...document.querySelectorAll('.hot-slot')].map(s => s.dataset.id));
    for (let i = 0; i < results.actions.hotbar.length; i++) {
      await page.keyboard.press(String(i + 1));
      await page.waitForTimeout(80);
      results.actions['key' + (i + 1)] = await page.evaluate(() => window.__melon.state.tool);
    }
  } catch (e) { results.actions.hotbarErr = String(e); }

  results.final = await snap();
  return results;
}
)(page);
